static void
efi_exclude_sbi_pmp_cb(struct efi_md *p, void *argp)
{
	bool *first = (bool *)argp;
	if (!*first)
		return;
	*first = false;
	if (p->md_type == EFI_MD_TYPE_BS_DATA) {
		physmem_exclude_region(p->md_phys,
		    min(p->md_pages * EFI_PAGE_SIZE, L2_SIZE),
		    EXFLAG_NOALLOC);
	}
}

